class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Check all possible substrings of length k
        for i in range(n - k + 1):
            # Check if substring s[i:i+k] has all same characters
            char = s[i]
            valid = True
            # Check all characters in the substring are the same
            for j in range(i, i + k):
                if s[j] != char:
                    valid = False
                    break
            if not valid:
                continue
            # Check character before (if exists) is different
            if i > 0 and s[i - 1] == char:
                continue
            # Check character after (if exists) is different
            if i + k < n and s[i + k] == char:
                continue
            return True
        return False
